SELECT pr.GOVERNORATE_CODE, g.NAME_AR GOVERNORATE_NAME_AR, pr.CITY_CODE, c.NAME_AR CITY_NAME_AR, a.FINANCIER_ID, o.ORG_NAME_AR FINANCIER_NAME_AR, COUNT(DISTINCT a.APPLICATION_ID) APPLICATION_COUNT, SUM(NVL(a.APPROVED_FINANCE_AMOUNT,0)) APPROVED_FINANCE_AMOUNT, SUM(NVL(a.TOTAL_SUBSIDY_AMOUNT,0)) SUBSIDY_AMOUNT FROM MFF_APPLICATIONS a JOIN MFF_ORGANIZATIONS o ON o.ORG_ID=a.FINANCIER_ID JOIN MFF_APPLICATION_PROPERTY ap ON ap.APPLICATION_ID=a.APPLICATION_ID AND ap.SELECTED_FLAG='Y' JOIN MFF_PROPERTIES pr ON pr.PROPERTY_ID=ap.PROPERTY_ID LEFT JOIN REF_MFF_GOVERNORATE g ON g.CODE=pr.GOVERNORATE_CODE LEFT JOIN REF_MFF_CITY c ON c.CODE=pr.CITY_CODE GROUP BY pr.GOVERNORATE_CODE,g.NAME_AR,pr.CITY_CODE,c.NAME_AR,a.FINANCIER_ID,o.ORG_NAME_AR;
